# ROBUSTNESS BACKEND — which ECU the robustness phases B/C/E/G/H/I talk to
# Manually written, not generated by testgen.py. Do not delete.
#
# By default every phase talks to conftest's inline ECU simulator, exactly as
# before: no licence, no harness, nothing to build. Under
# --can-interface=firmware, _sim() instead launches a fresh process of the
# compiled EDS harness (conftest_firmware.py) and _req() sends the same PDUs
# to it over ISO-TP, so the same assertions judge the real C stack (EDS#474).
#
# A firmware ECU deliberately exposes none of the simulator's attributes
# (session, sec_unlocked, dtcs, ...): a test that still reads or writes
# simulator state fails with AttributeError in firmware mode instead of
# silently checking the model. DTC status is set through set_dtc_status(), and
# an ECUReset reboots the harness (its transport reconnects), so state after a
# reset is the rebooted ECU's (EDS-toolchain#182/#183). Tests with no UDS path to the state they need
# are decorated @simulator_only(reason) and skip — with that reason — in
# firmware mode.
#
# Each test module imports `robustness_backend` (the autouse fixture) so the
# mode is set up and every harness it started is closed after the test.
from __future__ import annotations

import os
import sys
from pathlib import Path
from typing import Callable, List, Optional, Union

import pytest

sys.path.insert(0, os.path.dirname(__file__))
from conftest import _EcuSimulator, _InlineEcuState, _inline_handle
from conftest_firmware import FirmwareIsoTpTransport

_SIMULATOR_ONLY_ATTR = "_eds_simulator_only_reason"
_DIVERGENCE_ATTR = "_eds_firmware_divergence_issue"

_harness: Optional[Path] = None
_started: List["FirmwareEcu"] = []


class FirmwareEcu:
    """One fresh compiled-EDS harness process, standing in for _InlineEcuState."""

    # Without __slots__, `ecu.session = ...` would silently add an attribute
    # and the test would go on believing it had changed the ECU's state.
    __slots__ = ("_transport",)

    def __init__(self, binary: Path) -> None:
        self._transport = FirmwareIsoTpTransport(binary=binary)
        self._transport.start(timeout_s=10.0)

    def request(self, pdu: bytes) -> Optional[bytes]:
        return self._transport.request(pdu)

    def close(self) -> None:
        self._transport.close()


Ecu = Union[_InlineEcuState, FirmwareEcu]


def sim() -> Ecu:
    """A fresh ECU: the inline simulator, or a new harness in firmware mode."""
    if _harness is None:
        return _InlineEcuState()
    ecu = FirmwareEcu(_harness)
    _started.append(ecu)
    return ecu


def req(ecu: Ecu, pdu: bytes) -> Optional[bytes]:
    """Send one UDS request; None means no response (suppressed or timed out)."""
    if isinstance(ecu, FirmwareEcu):
        return ecu.request(pdu)
    return _inline_handle(pdu, ecu, False)


# ---------------------------------------------------------------------------
# State reached and observed through UDS only, so it works on either backend
# ---------------------------------------------------------------------------

def unlock(ecu: Ecu, level: int = 1) -> bool:
    """Enter the extended session and unlock `level` with a real seed/key exchange."""
    req(ecu, bytes([0x10, 0x03]))
    seed_rsp = req(ecu, bytes([0x27, 2 * level - 1]))
    if seed_rsp is None or seed_rsp[0] != 0x67:
        return False
    key = _EcuSimulator()._derive_key(bytes(seed_rsp[2:]), level)
    key_rsp = req(ecu, bytes([0x27, 2 * level]) + key)
    return key_rsp is not None and key_rsp[0] == 0x67


def is_unlocked(ecu: Ecu, level: int = 1) -> bool:
    """True if `level` is active: requestSeed answers an all-zero seed (ISO 14229-1).

    Side effect when locked: a real seed is issued and left pending, so call
    this as an observation at the end of a sequence, not in the middle.
    In the default session SecurityAccess is unavailable (NRC 0x7F), so no
    level can be active there.
    """
    rsp = req(ecu, bytes([0x27, 2 * level - 1]))
    if rsp is None or rsp[0] != 0x67:
        return False
    return not any(rsp[2:])


def set_dtc_status(ecu: Ecu, dtc_code: int, status: int) -> None:
    """Set a DTC's status the way an application monitor does.

    Simulator: writes the model's status byte. Firmware: the harness's control
    frame, which calls dtc_database_set_status() (and saves it to the NVM
    mirror) on the ECU thread (EDS-toolchain#183). No UDS request is sent.
    """
    if isinstance(ecu, FirmwareEcu):
        rc = ecu._transport.set_dtc_status(dtc_code, status)
        assert rc == 0, f"harness refused DTC 0x{dtc_code:06X} status 0x{status:02X}: uds_status 0x{rc:02X}"
        return
    for d in ecu.dtcs:
        if d["code"] == dtc_code:
            d["status"] = status
            return
    raise AssertionError(f"DTC 0x{dtc_code:06X} is not configured")


def simulator_only(reason: str) -> Callable:
    """Mark a test that cannot run against the C stack, and say why.

    A decorator rather than a pytest marker: pytest.ini is generated and runs
    with --strict-markers, so a new marker cannot be registered from here.
    """
    def mark(fn: Callable) -> Callable:
        setattr(fn, _SIMULATOR_ONLY_ATTR, reason)
        return fn
    return mark


def firmware_divergence(issue: str) -> Callable:
    """Mark a test the C stack fails because stack and simulator disagree.

    In firmware mode the test becomes a strict xfail naming the issue that
    tracks the divergence: it still runs, it still reports, and the moment the
    divergence is fixed it XPASSes and fails the run until the mark is removed.
    Simulator mode is unaffected.
    """
    def mark(fn: Callable) -> Callable:
        setattr(fn, _DIVERGENCE_ATTR, issue)
        return fn
    return mark


@pytest.fixture(autouse=True)
def robustness_backend(request: pytest.FixtureRequest):
    global _harness
    firmware = request.config.getoption("--can-interface") == "firmware"
    reason = getattr(request.function, _SIMULATOR_ONLY_ATTR, None)
    if firmware and reason:
        pytest.skip(f"simulator-only: {reason}")
    issue = getattr(request.function, _DIVERGENCE_ATTR, None)
    if firmware and issue:
        request.applymarker(pytest.mark.xfail(
            strict=True, reason=f"C stack and simulator diverge: {issue}"))
    # A harness that will not build or start must fail the run, not skip it
    # into a false green — harness_binary itself skips on a build failure.
    if firmware:
        try:
            _harness = request.getfixturevalue("harness_binary")
        except pytest.skip.Exception as exc:
            pytest.fail(f"--can-interface=firmware but no harness: {exc}", pytrace=False)
    else:
        _harness = None
    try:
        yield
    finally:
        while _started:
            _started.pop().close()
        _harness = None
